package com.resumethinking.platform.config;
import com.resumethinking.platform.auth.*; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.*; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.web.filter.OncePerRequestFilter; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import java.util.List;
@Configuration public class SecurityConfig {
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}
 @Bean SecurityFilterChain securityFilterChain(HttpSecurity http,JwtService jwt) throws Exception {http.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/v1/auth/register","/api/v1/auth/login","/actuator/health").permitAll().anyRequest().authenticated()).addFilterBefore(new JwtFilter(jwt),UsernamePasswordAuthenticationFilter.class); return http.build();}
 public static class JwtFilter extends OncePerRequestFilter {private final JwtService jwt; public JwtFilter(JwtService jwt){this.jwt=jwt;} protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws IOException,ServletException{String h=req.getHeader("Authorization"); if(h!=null&&h.startsWith("Bearer ")) jwt.parse(h.substring(7)).ifPresent(c->{req.setAttribute("actorId",c.subject()); req.setAttribute("role",c.role()); SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(c.subject().toString(),null,List.of(new SimpleGrantedAuthority("ROLE_"+c.role()))));}); chain.doFilter(req,res);}}
}
